insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values
  ('eb68ebdd-3f02-5330-8fb0-9731ffa2bb93', 'Região Episcopal Sant''Ana. Paróquia Nossa Senhora da Graça, a primeira de Belém (1617). Missas conferidas também no site da Catedral. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedebelem.com.br/paroquias-e-missas/","https://www.catedraldebelem.com.br/"}', 'alta'),
  ('d5332d79-7c9c-5276-a59c-b80223f2990e', 'Região Episcopal Santa Maria Goretti. Basílica e Santuário dos Padres Barnabitas. Horários e comunidades do site da Basílica; batem com o buscador da arquidiocese. Fora do formato: Adoração diante do altar na Capela Bom Pastor na 1ª e 3ª terça-feira do mês, sem hora publicada.; Adoração na primeira sexta-feira do mês, sem hora publicada.', '{"https://www.basilicadenazare.com.br/paroquia-de-nazare/horario-de-missa/horarios-de-missas","https://www.basilicadenazare.com.br/paroquia-de-nazare/comunidades","https://arquidiocesedebelem.com.br/paroquias-e-missas/"}', 'alta'),
  ('15398d9b-bb78-5d51-b0cd-80f19c742e60', 'Região Episcopal Coração Eucarístico de Jesus. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedebelem.com.br/paroquias-e-missas/"}', 'alta'),
  ('a9da44df-de65-5807-9ca5-27763e7c3ec9', 'Região Episcopal Coração Eucarístico de Jesus. O endereço publicado diz Belém (CEP 66670); o filtro de cidade do buscador põe em Ananindeua. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesedebelem.com.br/paroquias-e-missas/"}', 'alta'),
  ('f9f46a1a-3ff0-52bd-b317-116f24e224b2', 'Região Episcopal São João Batista.', '{"https://arquidiocesedebelem.com.br/paroquias-e-missas/"}', 'alta'),
  ('9fd72f3e-dfb2-555c-a239-49510e143413', 'Região Episcopal Santa Cruz.', '{"https://arquidiocesedebelem.com.br/paroquias-e-missas/"}', 'alta'),
  ('bc0261b2-afdc-568f-93b4-863f147455c2', 'Região Episcopal São João Batista.', '{"https://arquidiocesedebelem.com.br/paroquias-e-missas/"}', 'alta'),
  ('1d61aed2-3f37-5bb3-9488-d1cef0232abe', 'Região Episcopal Santa Cruz.', '{"https://arquidiocesedebelem.com.br/paroquias-e-missas/"}', 'alta'),
