  ('c1c428af-31ca-5e4b-8897-1b024d48c726', 'Região Episcopal Sant''Ana.', '{"https://arquidiocesedebelem.com.br/paroquias-e-missas/"}', 'alta'),
  ('b50aa081-729a-59e4-bb6f-d6fc8181d150', 'Região Episcopal Santa Cruz. Santuário arquidiocesano desde 2021.', '{"https://arquidiocesedebelem.com.br/paroquias-e-missas/"}', 'alta'),
  ('62e80000-dd78-518b-9a06-f6c91a230bdd', 'Região Episcopal São João Batista. Na Ilha de Caratateua, distrito de Outeiro.', '{"https://arquidiocesedebelem.com.br/paroquias-e-missas/"}', 'alta'),
