  ('6c552fa0-ed0c-510f-993e-930f179ca28c', 'Forania Nossa Senhora do Perpétuo Socorro. Fora do formato: Círio de Nazaré no 3º domingo de novembro.', '{"https://diocesedecastanhal.com.br/paroquias/31","https://diocesedecastanhal.com.br/paroquias/31"}', 'alta'),
  ('816b704b-6c60-5d1a-8fd7-d505ec0db8d5', 'Forania Nossa Senhora do Perpétuo Socorro.', '{"https://diocesedecastanhal.com.br/paroquias/32","https://diocesedecastanhal.com.br/paroquias/32"}', 'alta'),
  ('dfebf1aa-965f-5b88-85f8-d6b019a79ff2', 'Forania São Pedro. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedecastanhal.com.br/paroquias/33","https://diocesedecastanhal.com.br/paroquias/33"}', 'alta'),
